BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'Heart Attack vs Heart Failure vs Cardiac Arrest' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'Heart Attack vs Heart Failure vs Cardiac Arrest', 'Comparison of MI, HF, and arrest with priorities', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - MI/HF/Arrest (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'MI vs HF vs Cardiac Arrest - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI definition" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI definition" is most accurate?', '[{"id": "a", "text": "MI involves coronary blood-flow blockage."}, {"id": "b", "text": "MI occurs with absent pulse by definition."}, {"id": "c", "text": "MI is primarily chronic fluid overload."}, {"id": "d", "text": "STEMI and NSTEMI both have normal troponin."}]'::jsonb, '["a"]'::jsonb, 'Correct because Heart attack (MI) is blocked coronary blood flow causing heart muscle death. Treat suspected MI as time-sensitive myocardial injury requiring rapid reperfusion strategy.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HF definition" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "HF definition" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Women always present with classic elephant-on-chest pain."}, {"id": "b", "text": "HF patients may still have a pulse and consciousness."}, {"id": "c", "text": "HF means sudden cessation of all heart activity."}, {"id": "d", "text": "Thrombolytics are never used when PCI unavailable."}]'::jsonb, '["b"]'::jsonb, 'Correct because Heart failure is a condition where the heart is too weak or stiff to pump effectively. Differentiate pump failure from acute coronary occlusion and arrest during triage.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Cardiac arrest patients are usually awake and conversational."}, {"id": "b", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "c", "text": "Start CPR immediately when pulse is absent and patient is unresponsive."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["c"]'::jsonb, 'Correct because Cardiac arrest is sudden stop of all effective heart activity, causing no pulse and unresponsiveness. Start CPR immediately when pulse is absent and patient is unresponsive.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Use onset timeline to prioritize differential and response speed."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Cardiac arrest develops gradually over weeks."}]'::jsonb, '["b"]'::jsonb, 'Correct because MI onset is sudden in minutes, heart failure is gradual over weeks-months, and cardiac arrest is immediate in seconds. Use onset timeline to prioritize differential and response speed.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "MI always has no pulse at presentation."}, {"id": "b", "text": "Left HF has no respiratory symptoms."}, {"id": "c", "text": "Pulse is absent in uncomplicated HF."}, {"id": "d", "text": "HF patients may have weak but present pulse."}]'::jsonb, '["d"]'::jsonb, 'Correct because MI and HF generally have a pulse; cardiac arrest has no pulse and unconsciousness. Pulse check rapidly separates arrest from non-arrest chest pain syndromes.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI causes" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI causes" is most accurate?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "MI is caused only by chronic valve calcification."}, {"id": "c", "text": "Risk-profile plus symptoms should prompt urgent MI protocol activation."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["c"]'::jsonb, 'Correct because MI causes listed include atherosclerotic plaque and clot blocking coronary artery; risk factors include HTN, smoking, cholesterol, diabetes, sedentary lifestyle. Risk-profile plus symptoms should prompt urgent MI protocol activation.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "MI symptoms classic" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "MI symptoms classic" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "MI pain is always painless."}, {"id": "b", "text": "Clustered ischemic symptoms require immediate ACS workflow."}, {"id": "c", "text": "Thrombolytics are never used when PCI unavailable."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["b"]'::jsonb, 'Correct because Classic MI symptoms include crushing chest pain, radiation to left arm/jaw/neck/back, diaphoresis, nausea, SOB, and anxiety. Clustered ischemic symptoms require immediate ACS workflow.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "MI atypical in women" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "MI atypical in women" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Women always present with classic elephant-on-chest pain."}, {"id": "b", "text": "Pulmonary crackles are the defining right HF sign."}, {"id": "c", "text": "Avoid missed MI by recognizing atypical presentations."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["c"]'::jsonb, 'Correct because Women may present atypically with fatigue and epigastric pain. Avoid missed MI by recognizing atypical presentations.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Only chronic obesity triggers arrest."}, {"id": "b", "text": "STEMI and NSTEMI both have normal troponin."}, {"id": "c", "text": "HF is caused only by acute anaphylaxis."}, {"id": "d", "text": "Troponin elevates in both STEMI and NSTEMI."}]'::jsonb, '["d"]'::jsonb, 'Correct because STEMI has ST elevation with complete occlusion; NSTEMI has ST depression with partial occlusion; both have elevated troponin. ECG pattern plus troponin should direct urgency and intervention pathway.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Door-to-balloon target is 90 minutes for STEMI."}, {"id": "b", "text": "Strong peripheral pulse is typical of arrest."}, {"id": "c", "text": "Cardiac arrest patients remain fully alert."}, {"id": "d", "text": "Thrombolytics are never used when PCI unavailable."}]'::jsonb, '["a"]'::jsonb, 'Correct because STEMI requires PCI within 90 minutes; if PCI unavailable, thrombolytics are considered within 30 minutes. Time-to-reperfusion is critical for myocardial salvage.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MONA in MI" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MONA in MI" is most accurate?', '[{"id": "a", "text": "Initiate first-line MI measures while preparing definitive reperfusion."}, {"id": "b", "text": "MONA is a heart-failure-only acronym."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["a"]'::jsonb, 'Correct because MONA includes Morphine, Oxygen, Nitrates, and Aspirin in acute MI management from this note. Initiate first-line MI measures while preparing definitive reperfusion.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HF causes" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "HF causes" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "HF is caused only by acute anaphylaxis."}, {"id": "c", "text": "Address underlying cause while treating congestion and low output."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["c"]'::jsonb, 'Correct because Heart failure causes listed include post-MI scar, long-term hypertension, valve disease, cardiomyopathy, and COPD causing right-sided failure. Address underlying cause while treating congestion and low output.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Left-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Left-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Left HF has no respiratory symptoms."}, {"id": "b", "text": "Pulmonary edema is linked to left HF."}, {"id": "c", "text": "PEA should be defibrillated first."}, {"id": "d", "text": "Ascites is primary left HF sign."}]'::jsonb, '["b"]'::jsonb, 'Correct because Left HF signs include pulmonary edema, crackles, dyspnea, orthopnea, and PND. Recognize pulmonary congestion and position patient to improve breathing.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Right-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "Right-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Epinephrine is given once only then stopped."}, {"id": "b", "text": "Peripheral edema and weight gain are right HF signs."}, {"id": "c", "text": "Epinephrine is contraindicated in all arrest cases."}, {"id": "d", "text": "Pulmonary crackles are the defining right HF sign."}]'::jsonb, '["b"]'::jsonb, 'Correct because Right HF signs include JVD, peripheral edema, ascites, and weight gain. Track systemic venous congestion and fluid accumulation closely.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "HF treatment core" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "HF treatment core" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Combine pharmacologic and fluid/sodium strategies for decongestion and workload reduction."}, {"id": "c", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "d", "text": "Unlimited sodium intake is recommended."}]'::jsonb, '["b"]'::jsonb, 'Correct because HF treatment listed includes diuretics, ACE inhibitors/ARBs, beta-blockers, digoxin, low sodium diet, and fluid restriction. Combine pharmacologic and fluid/sodium strategies for decongestion and workload reduction.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Cardiac arrest rhythms" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Cardiac arrest rhythms" is most accurate?', '[{"id": "a", "text": "Arrest patients are typically ambulatory."}, {"id": "b", "text": "CAB means check rhythm before compressions."}, {"id": "c", "text": "PEA should be defibrillated first."}, {"id": "d", "text": "Rhythm identification guides intervention."}]'::jsonb, '["d"]'::jsonb, 'Correct because Shockable arrest rhythms are ventricular fibrillation and pulseless ventricular tachycardia; non-shockable are asystole and PEA. Rhythm classification determines defibrillation decisions during ACLS.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Cardiac arrest triggers" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "Cardiac arrest triggers" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Search reversible triggers while running high-quality resuscitation."}, {"id": "b", "text": "Only chronic obesity triggers arrest."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["a"]'::jsonb, 'Correct because Cardiac arrest can be triggered by MI, electrolyte imbalance, drowning, and drug overdose. Search reversible triggers while running high-quality resuscitation.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "MI is primarily chronic fluid overload."}, {"id": "b", "text": "Cardiac arrest patients remain fully alert."}, {"id": "c", "text": "MI occurs with absent pulse by definition."}, {"id": "d", "text": "No pulse and no breathing are key signs."}]'::jsonb, '["d"]'::jsonb, 'Correct because Key signs are sudden unresponsiveness, no pulse, no breathing, and cyanosis. Immediate recognition should trigger CPR without delay.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Epinephrine is contraindicated in all arrest cases."}, {"id": "b", "text": "Prioritize circulation immediately to preserve perfusion."}, {"id": "c", "text": "Breathing should always start before compressions."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["b"]'::jsonb, 'Correct because Resuscitation sequence emphasizes CAB: Compressions first, then Airway, then Breathing. Prioritize circulation immediately to preserve perfusion.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Shallow compressions are preferred."}, {"id": "b", "text": "Always check rhythm for several minutes before compressions."}, {"id": "c", "text": "High-quality compressions are central to survival in arrest."}, {"id": "d", "text": "Cardiac arrest patients are usually awake and conversational."}]'::jsonb, '["c"]'::jsonb, 'Correct because Compressions should be hard and fast, depth about 2 inches, at 100–120 per minute. High-quality compressions are central to survival in arrest.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Defibrillation use" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Defibrillation use" is most accurate?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "All rhythms are treated identically with no shocks."}, {"id": "c", "text": "HF means sudden cessation of all heart activity."}, {"id": "d", "text": "AED/defibrillation is indicated for V-fib or V-tach rhythms."}]'::jsonb, '["d"]'::jsonb, 'Correct because AED/defibrillation is indicated for V-fib or V-tach rhythms. Deliver shock promptly for shockable rhythms while minimizing pauses.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Epinephrine timing" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "Epinephrine timing" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Epinephrine is contraindicated in all arrest cases."}, {"id": "c", "text": "Follow medication interval while maintaining uninterrupted CPR cycles."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["c"]'::jsonb, 'Correct because Epinephrine is given every 3–5 minutes during cardiac arrest management. Follow medication interval while maintaining uninterrupted CPR cycles.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Rhythm check should not delay first compressions."}, {"id": "b", "text": "MI is caused only by chronic valve calcification."}, {"id": "c", "text": "MI occurs with absent pulse by definition."}, {"id": "d", "text": "No pulse should be observed without intervention."}]'::jsonb, '["a"]'::jsonb, 'Correct because NCLEX rule in note: if no pulse, start CPR first and do not delay compressions to check rhythm. Immediate compressions outrank delayed diagnostic steps in pulseless patients.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "HF means sudden cessation of all heart activity."}, {"id": "b", "text": "MI and arrest share identical first actions."}, {"id": "c", "text": "Arrest patients are typically ambulatory."}, {"id": "d", "text": "MI can present with chest pain in conscious patient."}]'::jsonb, '["d"]'::jsonb, 'Correct because MI patient is usually awake and in pain, while cardiac arrest patient is unresponsive and pulseless. Distinguish syndrome quickly to choose PCI pathway vs resuscitation pathway.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Arrest diagnosis depends on BNP trend first."}, {"id": "b", "text": "Women always present with classic elephant-on-chest pain."}, {"id": "c", "text": "Select diagnostics that match syndrome and urgency."}, {"id": "d", "text": "MI is caused only by chronic valve calcification."}]'::jsonb, '["c"]'::jsonb, 'Correct because Key tests listed: MI uses 12-lead ECG and troponin; HF uses BNP/echo/chest X-ray; arrest uses rhythm analysis for shockability. Select diagnostics that match syndrome and urgency.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI definition" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI definition" is most accurate?', '[{"id": "a", "text": "MI is primarily chronic fluid overload."}, {"id": "b", "text": "MI is an acute emergency condition."}, {"id": "c", "text": "NSTEMI requires ST elevation."}, {"id": "d", "text": "HF generally begins in seconds."}]'::jsonb, '["b"]'::jsonb, 'Correct because Heart attack (MI) is blocked coronary blood flow causing heart muscle death. Treat suspected MI as time-sensitive myocardial injury requiring rapid reperfusion strategy.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HF definition" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "HF definition" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "HF means sudden cessation of all heart activity."}, {"id": "b", "text": "MI always has no pulse at presentation."}, {"id": "c", "text": "HF is impaired pumping/filling efficiency."}, {"id": "d", "text": "Pulse is absent in uncomplicated HF."}]'::jsonb, '["c"]'::jsonb, 'Correct because Heart failure is a condition where the heart is too weak or stiff to pump effectively. Differentiate pump failure from acute coronary occlusion and arrest during triage.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "STEMI and NSTEMI both have normal troponin."}, {"id": "b", "text": "Cardiac arrest is gradual over months."}, {"id": "c", "text": "Immediate resuscitation is required in arrest."}, {"id": "d", "text": "MI is caused only by chronic valve calcification."}]'::jsonb, '["c"]'::jsonb, 'Correct because Cardiac arrest is sudden stop of all effective heart activity, causing no pulse and unresponsiveness. Start CPR immediately when pulse is absent and patient is unresponsive.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "MI onset is sudden in minutes, heart failure is gradual over weeks-months, and cardiac arrest is immediate in seconds."}, {"id": "b", "text": "Cardiac arrest develops gradually over weeks."}, {"id": "c", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["a"]'::jsonb, 'Correct because MI onset is sudden in minutes, heart failure is gradual over weeks-months, and cardiac arrest is immediate in seconds. Use onset timeline to prioritize differential and response speed.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Pulse check rapidly separates arrest from non-arrest chest pain syndromes."}, {"id": "c", "text": "MI always has no pulse at presentation."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["b"]'::jsonb, 'Correct because MI and HF generally have a pulse; cardiac arrest has no pulse and unconsciousness. Pulse check rapidly separates arrest from non-arrest chest pain syndromes.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI causes" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MI causes" is most accurate?', '[{"id": "a", "text": "Risk-profile plus symptoms should prompt urgent MI protocol activation."}, {"id": "b", "text": "MI is caused only by chronic valve calcification."}, {"id": "c", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["a"]'::jsonb, 'Correct because MI causes listed include atherosclerotic plaque and clot blocking coronary artery; risk factors include HTN, smoking, cholesterol, diabetes, sedentary lifestyle. Risk-profile plus symptoms should prompt urgent MI protocol activation.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "MI symptoms classic" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "MI symptoms classic" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Classic MI symptoms include crushing chest pain, radiation to left arm/jaw/neck/back, diaphoresis, nausea, SOB, and anxiety."}, {"id": "c", "text": "MI pain is always painless."}, {"id": "d", "text": "Because symptoms are mild, urgent action can be deferred safely."}]'::jsonb, '["b"]'::jsonb, 'Correct because Classic MI symptoms include crushing chest pain, radiation to left arm/jaw/neck/back, diaphoresis, nausea, SOB, and anxiety. Clustered ischemic symptoms require immediate ACS workflow.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "MI atypical in women" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "MI atypical in women" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Women may present atypically with fatigue and epigastric pain."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Women always present with classic elephant-on-chest pain."}]'::jsonb, '["b"]'::jsonb, 'Correct because Women may present atypically with fatigue and epigastric pain. Avoid missed MI by recognizing atypical presentations.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "STEMI and NSTEMI both have normal troponin."}, {"id": "b", "text": "ECG pattern plus troponin should direct urgency and intervention pathway."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["b"]'::jsonb, 'Correct because STEMI has ST elevation with complete occlusion; NSTEMI has ST depression with partial occlusion; both have elevated troponin. ECG pattern plus troponin should direct urgency and intervention pathway.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "NSTEMI uses anticoagulants and cardiac cath strategy."}, {"id": "b", "text": "Cardiac arrest patients remain fully alert."}, {"id": "c", "text": "Strong peripheral pulse is typical of arrest."}, {"id": "d", "text": "Thrombolytics are never used when PCI unavailable."}]'::jsonb, '["a"]'::jsonb, 'Correct because STEMI requires PCI within 90 minutes; if PCI unavailable, thrombolytics are considered within 30 minutes. Time-to-reperfusion is critical for myocardial salvage.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MONA in MI" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "MONA in MI" is most accurate?', '[{"id": "a", "text": "MONA is a heart-failure-only acronym."}, {"id": "b", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "MONA includes Morphine, Oxygen, Nitrates, and Aspirin in acute MI management from this note."}]'::jsonb, '["d"]'::jsonb, 'Correct because MONA includes Morphine, Oxygen, Nitrates, and Aspirin in acute MI management from this note. Initiate first-line MI measures while preparing definitive reperfusion.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "HF causes" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "HF causes" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Address underlying cause while treating congestion and low output."}, {"id": "c", "text": "HF is caused only by acute anaphylaxis."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["b"]'::jsonb, 'Correct because Heart failure causes listed include post-MI scar, long-term hypertension, valve disease, cardiomyopathy, and COPD causing right-sided failure. Address underlying cause while treating congestion and low output.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Left-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Left-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Recognize pulmonary congestion and position patient to improve breathing."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Left HF has no respiratory symptoms."}]'::jsonb, '["b"]'::jsonb, 'Correct because Left HF signs include pulmonary edema, crackles, dyspnea, orthopnea, and PND. Recognize pulmonary congestion and position patient to improve breathing.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Right-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "Right-sided HF signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Track systemic venous congestion and fluid accumulation closely."}, {"id": "b", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "c", "text": "Pulmonary crackles are the defining right HF sign."}, {"id": "d", "text": "Rhythm assessment should always precede compressions in pulseless states."}]'::jsonb, '["a"]'::jsonb, 'Correct because Right HF signs include JVD, peripheral edema, ascites, and weight gain. Track systemic venous congestion and fluid accumulation closely.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "HF treatment core" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "HF treatment core" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "c", "text": "Unlimited sodium intake is recommended."}, {"id": "d", "text": "Combine pharmacologic and fluid/sodium strategies for decongestion and workload reduction."}]'::jsonb, '["d"]'::jsonb, 'Correct because HF treatment listed includes diuretics, ACE inhibitors/ARBs, beta-blockers, digoxin, low sodium diet, and fluid restriction. Combine pharmacologic and fluid/sodium strategies for decongestion and workload reduction.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Cardiac arrest rhythms" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Cardiac arrest rhythms" is most accurate?', '[{"id": "a", "text": "V-fib and pulseless V-tach are shockable."}, {"id": "b", "text": "Arrest patients are typically ambulatory."}, {"id": "c", "text": "PEA should be defibrillated first."}, {"id": "d", "text": "CAB means check rhythm before compressions."}]'::jsonb, '["a"]'::jsonb, 'Correct because Shockable arrest rhythms are ventricular fibrillation and pulseless ventricular tachycardia; non-shockable are asystole and PEA. Rhythm classification determines defibrillation decisions during ACLS.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Cardiac arrest triggers" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "Cardiac arrest triggers" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "b", "text": "Cardiac arrest can be triggered by MI, electrolyte imbalance, drowning, and drug overdose."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Only chronic obesity triggers arrest."}]'::jsonb, '["b"]'::jsonb, 'Correct because Cardiac arrest can be triggered by MI, electrolyte imbalance, drowning, and drug overdose. Search reversible triggers while running high-quality resuscitation.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Immediate recognition should trigger CPR without delay."}, {"id": "c", "text": "Strong peripheral pulse is typical of arrest."}, {"id": "d", "text": "All rhythms are treated identically with no shocks."}]'::jsonb, '["b"]'::jsonb, 'Correct because Key signs are sudden unresponsiveness, no pulse, no breathing, and cyanosis. Immediate recognition should trigger CPR without delay.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Airway follows compressions in sequence."}, {"id": "b", "text": "CAB means check rhythm before compressions."}, {"id": "c", "text": "Arrest diagnosis depends on BNP trend first."}, {"id": "d", "text": "Epinephrine is given once only then stopped."}]'::jsonb, '["a"]'::jsonb, 'Correct because Resuscitation sequence emphasizes CAB: Compressions first, then Airway, then Breathing. Prioritize circulation immediately to preserve perfusion.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Shallow compressions are preferred."}, {"id": "c", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "d", "text": "Compressions should be hard and fast, depth about 2 inches, at 100–120 per minute."}]'::jsonb, '["d"]'::jsonb, 'Correct because Compressions should be hard and fast, depth about 2 inches, at 100–120 per minute. High-quality compressions are central to survival in arrest.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Defibrillation use" is most accurate?', 'According to the Heart Attack vs Heart Failure vs Cardiac Arrest note, which statement about "Defibrillation use" is most accurate?', '[{"id": "a", "text": "Arrest patients are typically ambulatory."}, {"id": "b", "text": "Defibrillation depends on rhythm type."}, {"id": "c", "text": "AED is first-line for asystole."}, {"id": "d", "text": "HF always presents with no pulse."}]'::jsonb, '["b"]'::jsonb, 'Correct because AED/defibrillation is indicated for V-fib or V-tach rhythms. Deliver shock promptly for shockable rhythms while minimizing pauses.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Epinephrine timing" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', 'The nurse is reviewing "Epinephrine timing" in Heart Attack vs Heart Failure vs Cardiac Arrest. Which statement is correct?', '[{"id": "a", "text": "Arrest diagnosis depends on BNP trend first."}, {"id": "b", "text": "Epinephrine interval is every 3–5 minutes."}, {"id": "c", "text": "Epinephrine is given once only then stopped."}, {"id": "d", "text": "MI always has no pulse at presentation."}]'::jsonb, '["b"]'::jsonb, 'Correct because Epinephrine is given every 3–5 minutes during cardiac arrest management. Follow medication interval while maintaining uninterrupted CPR cycles.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'Which clinical judgment is most accurate regarding "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Always check rhythm for several minutes before compressions."}, {"id": "b", "text": "Rhythm assessment should always precede compressions in pulseless states."}, {"id": "c", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "d", "text": "Immediate compressions outrank delayed diagnostic steps in pulseless patients."}]'::jsonb, '["d"]'::jsonb, 'Correct because NCLEX rule in note: if no pulse, start CPR first and do not delay compressions to check rhythm. Immediate compressions outrank delayed diagnostic steps in pulseless patients.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest?', 'In rapid prioritization, which statement is most consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest?', '[{"id": "a", "text": "Because symptoms are mild, urgent action can be deferred safely."}, {"id": "b", "text": "Arrest presents with unresponsiveness and absent pulse."}, {"id": "c", "text": "MI and arrest share identical first actions."}, {"id": "d", "text": "HF means sudden cessation of all heart activity."}]'::jsonb, '["b"]'::jsonb, 'Correct because MI patient is usually awake and in pain, while cardiac arrest patient is unresponsive and pulseless. Distinguish syndrome quickly to choose PCI pathway vs resuscitation pathway.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', 'Which conclusion about "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest would the nurse recognize as correct?', '[{"id": "a", "text": "Arrest diagnosis depends on BNP trend first."}, {"id": "b", "text": "Cardiac arrest patients are usually awake and conversational."}, {"id": "c", "text": "Rhythm analysis identifies shockable arrest rhythms."}, {"id": "d", "text": "Women always present with classic elephant-on-chest pain."}]'::jsonb, '["c"]'::jsonb, 'Correct because Key tests listed: MI uses 12-lead ECG and troponin; HF uses BNP/echo/chest X-ray; arrest uses rhythm analysis for shockability. Select diagnostics that match syndrome and urgency.', 'MI vs HF vs Cardiac Arrest - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "MI definition" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "MI definition" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "MI occurs with absent pulse by definition."}, {"id": "b", "text": "MI is an acute emergency condition."}, {"id": "c", "text": "MI involves coronary blood-flow blockage."}, {"id": "d", "text": "Myocardial tissue death occurs with sustained ischemia."}, {"id": "e", "text": "MI is primarily chronic fluid overload."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Heart attack (MI) is blocked coronary blood flow causing heart muscle death.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "HF definition"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "HF definition"? (Select all that apply)', '[{"id": "a", "text": "HF patients may still have a pulse and consciousness."}, {"id": "b", "text": "HF always presents with no pulse."}, {"id": "c", "text": "HF often develops more gradually than MI."}, {"id": "d", "text": "HF is impaired pumping/filling efficiency."}, {"id": "e", "text": "HF means sudden cessation of all heart activity."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Heart failure is a condition where the heart is too weak or stiff to pump effectively.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Cardiac arrest has absent pulse."}, {"id": "b", "text": "Cardiac arrest patients are unconscious."}, {"id": "c", "text": "Immediate resuscitation is required in arrest."}, {"id": "d", "text": "Cardiac arrest is gradual over months."}, {"id": "e", "text": "Cardiac arrest patients are usually awake and conversational."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Cardiac arrest is sudden stop of all effective heart activity, causing no pulse and unresponsiveness.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 53, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "HF generally begins in seconds."}, {"id": "b", "text": "MI is sudden."}, {"id": "c", "text": "HF is typically gradual."}, {"id": "d", "text": "Cardiac arrest develops gradually over weeks."}, {"id": "e", "text": "Cardiac arrest occurs in seconds."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: MI onset is sudden in minutes, heart failure is gradual over weeks-months, and cardiac arrest is immediate in seconds.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 54, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "MI always has no pulse at presentation."}, {"id": "b", "text": "Pulse is absent in uncomplicated HF."}, {"id": "c", "text": "Cardiac arrest has no pulse."}, {"id": "d", "text": "HF patients may have weak but present pulse."}, {"id": "e", "text": "MI often presents while conscious."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MI and HF generally have a pulse; cardiac arrest has no pulse and unconsciousness.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 55, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "MI causes" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "MI causes" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "Smoking lowers MI risk."}, {"id": "b", "text": "Sedentary lifestyle is listed as risk."}, {"id": "c", "text": "HTN/smoking/cholesterol/diabetes are listed risks."}, {"id": "d", "text": "Atherosclerosis and thrombosis are listed MI causes."}, {"id": "e", "text": "MI is caused only by chronic valve calcification."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: MI causes listed include atherosclerotic plaque and clot blocking coronary artery; risk factors include HTN, smoking, cholesterol, diabetes, sedentary lifestyle.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 56, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "MI symptoms classic"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "MI symptoms classic"? (Select all that apply)', '[{"id": "a", "text": "Radiation to arm/jaw/neck/back is listed."}, {"id": "b", "text": "Radiation is absent in MI."}, {"id": "c", "text": "Crushing chest pain is described in MI."}, {"id": "d", "text": "Diaphoresis and nausea are listed features."}, {"id": "e", "text": "MI pain is always painless."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Classic MI symptoms include crushing chest pain, radiation to left arm/jaw/neck/back, diaphoresis, nausea, SOB, and anxiety.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 57, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
