  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "STEMI vs NSTEMI" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "STEMI and NSTEMI both have normal troponin."}, {"id": "b", "text": "Troponin elevates in both STEMI and NSTEMI."}, {"id": "c", "text": "NSTEMI requires ST elevation."}, {"id": "d", "text": "STEMI is complete occlusion."}, {"id": "e", "text": "NSTEMI is partial occlusion."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: STEMI has ST elevation with complete occlusion; NSTEMI has ST depression with partial occlusion; both have elevated troponin.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 59, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "MI treatment timing" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Thrombolytics are considered if PCI unavailable within 30 minutes."}, {"id": "b", "text": "Door-to-balloon target is 90 minutes for STEMI."}, {"id": "c", "text": "NSTEMI uses anticoagulants and cardiac cath strategy."}, {"id": "d", "text": "STEMI reperfusion can wait 24 hours."}, {"id": "e", "text": "Thrombolytics are never used when PCI unavailable."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: STEMI requires PCI within 90 minutes; if PCI unavailable, thrombolytics are considered within 30 minutes.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 60, 1, true);
