  VALUES (v_test_id, v_topic_id, 'Which statements about "MONA in MI" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "MONA in MI" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "MONA excludes aspirin."}, {"id": "b", "text": "Morphine is in MONA."}, {"id": "c", "text": "MONA is a heart-failure-only acronym."}, {"id": "d", "text": "Aspirin is in MONA."}, {"id": "e", "text": "Nitrates are in MONA."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MONA includes Morphine, Oxygen, Nitrates, and Aspirin in acute MI management from this note.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 61, 1, true);
