  VALUES (v_test_id, v_topic_id, 'Which statements about "Cardiac arrest rhythms" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "Cardiac arrest rhythms" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "PEA should be defibrillated first."}, {"id": "b", "text": "Asystole is shockable."}, {"id": "c", "text": "Asystole and PEA are non-shockable."}, {"id": "d", "text": "V-fib and pulseless V-tach are shockable."}, {"id": "e", "text": "Rhythm identification guides intervention."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Shockable arrest rhythms are ventricular fibrillation and pulseless ventricular tachycardia; non-shockable are asystole and PEA.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 66, 1, true);
