  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Cardiac arrest triggers"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Cardiac arrest triggers"? (Select all that apply)', '[{"id": "a", "text": "Drowning and drug overdose are listed triggers."}, {"id": "b", "text": "MI is a listed trigger for arrest."}, {"id": "c", "text": "Electrolyte imbalance is listed trigger."}, {"id": "d", "text": "Only chronic obesity triggers arrest."}, {"id": "e", "text": "Drug overdose cannot cause arrest."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Cardiac arrest can be triggered by MI, electrolyte imbalance, drowning, and drug overdose.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 67, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Sudden unconsciousness is expected."}, {"id": "b", "text": "Cyanosis can be seen in arrest."}, {"id": "c", "text": "Cardiac arrest patients remain fully alert."}, {"id": "d", "text": "Strong peripheral pulse is typical of arrest."}, {"id": "e", "text": "No pulse and no breathing are key signs."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Key signs are sudden unresponsiveness, no pulse, no breathing, and cyanosis.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 68, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Airway follows compressions in sequence."}, {"id": "b", "text": "Breathing should always start before compressions."}, {"id": "c", "text": "CAB means check rhythm before compressions."}, {"id": "d", "text": "Breathing follows airway in sequence."}, {"id": "e", "text": "Compressions come first in CAB."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Resuscitation sequence emphasizes CAB: Compressions first, then Airway, then Breathing.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 69, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Shallow compressions are preferred."}, {"id": "b", "text": "Hard, fast compressions are emphasized."}, {"id": "c", "text": "Target rate is 100–120/min."}, {"id": "d", "text": "Compression rate should be 40/min."}, {"id": "e", "text": "Depth target is around 2 inches."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Compressions should be hard and fast, depth about 2 inches, at 100–120 per minute.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 70, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Defibrillation use" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "Defibrillation use" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "All rhythms are treated identically with no shocks."}, {"id": "b", "text": "Defibrillation depends on rhythm type."}, {"id": "c", "text": "AED is first-line for asystole."}, {"id": "d", "text": "AED is used for V-fib."}, {"id": "e", "text": "AED is used for V-tach."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: AED/defibrillation is indicated for V-fib or V-tach rhythms.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 71, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Epinephrine timing"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Epinephrine timing"? (Select all that apply)', '[{"id": "a", "text": "Epinephrine is given once only then stopped."}, {"id": "b", "text": "Drug timing complements CPR, not replaces it."}, {"id": "c", "text": "Epinephrine interval is every 3–5 minutes."}, {"id": "d", "text": "Epinephrine is contraindicated in all arrest cases."}, {"id": "e", "text": "Epinephrine is part of arrest protocol."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Epinephrine is given every 3–5 minutes during cardiac arrest management.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 72, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "This is highlighted as a key NCLEX rule."}, {"id": "b", "text": "Always check rhythm for several minutes before compressions."}, {"id": "c", "text": "No pulse should be observed without intervention."}, {"id": "d", "text": "No pulse triggers CPR immediately."}, {"id": "e", "text": "Rhythm check should not delay first compressions."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: NCLEX rule in note: if no pulse, start CPR first and do not delay compressions to check rhythm.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 73, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Arrest patients are typically ambulatory."}, {"id": "b", "text": "Both are emergencies but require different immediate responses."}, {"id": "c", "text": "MI can present with chest pain in conscious patient."}, {"id": "d", "text": "MI and arrest share identical first actions."}, {"id": "e", "text": "Arrest presents with unresponsiveness and absent pulse."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: MI patient is usually awake and in pain, while cardiac arrest patient is unresponsive and pulseless.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 74, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Troponin and ECG are key for MI."}, {"id": "b", "text": "Rhythm analysis identifies shockable arrest rhythms."}, {"id": "c", "text": "HF diagnosis relies only on troponin."}, {"id": "d", "text": "Arrest diagnosis depends on BNP trend first."}, {"id": "e", "text": "BNP/echo/chest X-ray are listed for HF."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Key tests listed: MI uses 12-lead ECG and troponin; HF uses BNP/echo/chest X-ray; arrest uses rhythm analysis for shockability.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 75, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "MI definition" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "MI definition" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "MI involves coronary blood-flow blockage."}, {"id": "b", "text": "MI occurs with absent pulse by definition."}, {"id": "c", "text": "Myocardial tissue death occurs with sustained ischemia."}, {"id": "d", "text": "MI is an acute emergency condition."}, {"id": "e", "text": "MI is primarily chronic fluid overload."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Heart attack (MI) is blocked coronary blood flow causing heart muscle death.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 76, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "HF definition"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "HF definition"? (Select all that apply)', '[{"id": "a", "text": "HF means sudden cessation of all heart activity."}, {"id": "b", "text": "HF is impaired pumping/filling efficiency."}, {"id": "c", "text": "HF often develops more gradually than MI."}, {"id": "d", "text": "HF always presents with no pulse."}, {"id": "e", "text": "HF patients may still have a pulse and consciousness."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Heart failure is a condition where the heart is too weak or stiff to pump effectively.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 77, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiac arrest definition" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Cardiac arrest has absent pulse."}, {"id": "b", "text": "Cardiac arrest patients are usually awake and conversational."}, {"id": "c", "text": "Cardiac arrest patients are unconscious."}, {"id": "d", "text": "Immediate resuscitation is required in arrest."}, {"id": "e", "text": "Cardiac arrest is gradual over months."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Cardiac arrest is sudden stop of all effective heart activity, causing no pulse and unresponsiveness.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 78, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "Onset differences" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "HF is typically gradual."}, {"id": "b", "text": "HF generally begins in seconds."}, {"id": "c", "text": "Cardiac arrest develops gradually over weeks."}, {"id": "d", "text": "MI is sudden."}, {"id": "e", "text": "Cardiac arrest occurs in seconds."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MI onset is sudden in minutes, heart failure is gradual over weeks-months, and cardiac arrest is immediate in seconds.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 79, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Pulse consciousness pattern" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "MI always has no pulse at presentation."}, {"id": "b", "text": "MI often presents while conscious."}, {"id": "c", "text": "Pulse is absent in uncomplicated HF."}, {"id": "d", "text": "HF patients may have weak but present pulse."}, {"id": "e", "text": "Cardiac arrest has no pulse."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MI and HF generally have a pulse; cardiac arrest has no pulse and unconsciousness.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 80, 1, true);
