  VALUES (v_test_id, v_topic_id, 'Which statements about "MI causes" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "MI causes" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "MI is caused only by chronic valve calcification."}, {"id": "b", "text": "HTN/smoking/cholesterol/diabetes are listed risks."}, {"id": "c", "text": "Atherosclerosis and thrombosis are listed MI causes."}, {"id": "d", "text": "Smoking lowers MI risk."}, {"id": "e", "text": "Sedentary lifestyle is listed as risk."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: MI causes listed include atherosclerotic plaque and clot blocking coronary artery; risk factors include HTN, smoking, cholesterol, diabetes, sedentary lifestyle.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 81, 1, true);
