  VALUES (v_test_id, v_topic_id, 'Which statements about "Cardiac arrest rhythms" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "Cardiac arrest rhythms" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "V-fib and pulseless V-tach are shockable."}, {"id": "b", "text": "Asystole is shockable."}, {"id": "c", "text": "Asystole and PEA are non-shockable."}, {"id": "d", "text": "PEA should be defibrillated first."}, {"id": "e", "text": "Rhythm identification guides intervention."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Shockable arrest rhythms are ventricular fibrillation and pulseless ventricular tachycardia; non-shockable are asystole and PEA.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 91, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Cardiac arrest triggers"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Cardiac arrest triggers"? (Select all that apply)', '[{"id": "a", "text": "Drug overdose cannot cause arrest."}, {"id": "b", "text": "Only chronic obesity triggers arrest."}, {"id": "c", "text": "Drowning and drug overdose are listed triggers."}, {"id": "d", "text": "Electrolyte imbalance is listed trigger."}, {"id": "e", "text": "MI is a listed trigger for arrest."}]'::jsonb, '["c", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Cardiac arrest can be triggered by MI, electrolyte imbalance, drowning, and drug overdose.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 92, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "Cardiac arrest signs" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Strong peripheral pulse is typical of arrest."}, {"id": "b", "text": "Cyanosis can be seen in arrest."}, {"id": "c", "text": "Cardiac arrest patients remain fully alert."}, {"id": "d", "text": "No pulse and no breathing are key signs."}, {"id": "e", "text": "Sudden unconsciousness is expected."}]'::jsonb, '["b", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Key signs are sudden unresponsiveness, no pulse, no breathing, and cyanosis.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 93, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "CAB order" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Breathing follows airway in sequence."}, {"id": "b", "text": "Airway follows compressions in sequence."}, {"id": "c", "text": "Compressions come first in CAB."}, {"id": "d", "text": "Breathing should always start before compressions."}, {"id": "e", "text": "CAB means check rhythm before compressions."}]'::jsonb, '["a", "b", "c"]'::jsonb, 'Correct selections align with note-based facts: Resuscitation sequence emphasizes CAB: Compressions first, then Airway, then Breathing.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 94, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Compression quality" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Shallow compressions are preferred."}, {"id": "b", "text": "Hard, fast compressions are emphasized."}, {"id": "c", "text": "Depth target is around 2 inches."}, {"id": "d", "text": "Target rate is 100–120/min."}, {"id": "e", "text": "Compression rate should be 40/min."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Compressions should be hard and fast, depth about 2 inches, at 100–120 per minute.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 95, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "Defibrillation use" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', 'Which statements about "Defibrillation use" in Heart Attack vs Heart Failure vs Cardiac Arrest are correct? (Select all that apply)', '[{"id": "a", "text": "All rhythms are treated identically with no shocks."}, {"id": "b", "text": "Defibrillation depends on rhythm type."}, {"id": "c", "text": "AED is used for V-tach."}, {"id": "d", "text": "AED is used for V-fib."}, {"id": "e", "text": "AED is first-line for asystole."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: AED/defibrillation is indicated for V-fib or V-tach rhythms.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 96, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Epinephrine timing"? (Select all that apply)', 'For Heart Attack vs Heart Failure vs Cardiac Arrest, which findings or actions relate to "Epinephrine timing"? (Select all that apply)', '[{"id": "a", "text": "Epinephrine interval is every 3–5 minutes."}, {"id": "b", "text": "Drug timing complements CPR, not replaces it."}, {"id": "c", "text": "Epinephrine is contraindicated in all arrest cases."}, {"id": "d", "text": "Epinephrine is given once only then stopped."}, {"id": "e", "text": "Epinephrine is part of arrest protocol."}]'::jsonb, '["a", "b", "e"]'::jsonb, 'Correct selections align with note-based facts: Epinephrine is given every 3–5 minutes during cardiac arrest management.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 97, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'The nurse is planning care. Which items apply to "No pulse NCLEX rule" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "No pulse should be observed without intervention."}, {"id": "b", "text": "This is highlighted as a key NCLEX rule."}, {"id": "c", "text": "Rhythm check should not delay first compressions."}, {"id": "d", "text": "No pulse triggers CPR immediately."}, {"id": "e", "text": "Always check rhythm for several minutes before compressions."}]'::jsonb, '["b", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: NCLEX rule in note: if no pulse, start CPR first and do not delay compressions to check rhythm.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 98, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'Which of the following are consistent with "MI vs arrest distinction" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "MI can present with chest pain in conscious patient."}, {"id": "b", "text": "Arrest patients are typically ambulatory."}, {"id": "c", "text": "MI and arrest share identical first actions."}, {"id": "d", "text": "Arrest presents with unresponsiveness and absent pulse."}, {"id": "e", "text": "Both are emergencies but require different immediate responses."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: MI patient is usually awake and in pain, while cardiac arrest patient is unresponsive and pulseless.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 99, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', 'During reassessment, which observations align with "Key tests by syndrome" in Heart Attack vs Heart Failure vs Cardiac Arrest? (Select all that apply)', '[{"id": "a", "text": "Rhythm analysis identifies shockable arrest rhythms."}, {"id": "b", "text": "BNP/echo/chest X-ray are listed for HF."}, {"id": "c", "text": "HF diagnosis relies only on troponin."}, {"id": "d", "text": "Troponin and ECG are key for MI."}, {"id": "e", "text": "Arrest diagnosis depends on BNP trend first."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Key tests listed: MI uses 12-lead ECG and troponin; HF uses BNP/echo/chest X-ray; arrest uses rhythm analysis for shockability.', 'MI vs HF vs Cardiac Arrest - NCLEX', true, 100, 1, true);
